package auth.crossservice

import java.nio.charset.{Charset, StandardCharsets}
import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

import scala.util.Try

object TokenEncoding {
  val SERVICE_CHARSET: Charset = StandardCharsets.UTF_8

  def normalizeServiceId(serviceId: String): Array[Byte] = {
    // Normalize unicode to NFC form for consistent comparison
    val normalized = java.text.Normalizer.normalize(serviceId, java.text.Normalizer.Form.NFC)
    normalized.getBytes(SERVICE_CHARSET)
  }

  def encodeTokenPayload(payload: String): Array[Byte] = {
    // Use modified base64 for URL safety
    Base64.getUrlEncoder.withoutPadding().encode(payload.getBytes(SERVICE_CHARSET))
  }
}

case class ServiceCredential(serviceId: String, secret: Array[Byte], permissions: Set[String])

class CrossServiceAuthenticator(trustedServices: Map[String, ServiceCredential]) {

  private val HMAC_ALGORITHM = "HmacSHA256"
  private val TOKEN_SEPARATOR = "|"
  private val FIELD_SEPARATOR = ":"

  def generateToken(serviceId: String, targetService: String, timestamp: Long): String = {
    val credential = trustedServices.getOrElse(serviceId, 
      throw new SecurityException(s"Unknown service: $serviceId"))

    val payload = s"${serviceId}${FIELD_SEPARATOR}${targetService}${FIELD_SEPARATOR}${timestamp}"
    val signature = computeHmac(credential.secret, payload)
    val encodedPayload = new String(TokenEncoding.encodeTokenPayload(payload), TokenEncoding.SERVICE_CHARSET)
    val encodedSignature = Base64.getUrlEncoder.withoutPadding().encodeToString(signature)

    s"${encodedPayload}${TOKEN_SEPARATOR}${encodedSignature}"
  }

  def validateToken(token: String, expectedTarget: String): Option[ServiceCredential] = {
    val parts = token.split("\\" + TOKEN_SEPARATOR, 2)
    if (parts.length != 2) return None

    // Safely decode the payload; malformed Base64 results in an authentication failure (None)
    val decodedPayload = Try(
      new String(
        Base64.getUrlDecoder.decode(parts(0).getBytes(TokenEncoding.SERVICE_CHARSET)),
        TokenEncoding.SERVICE_CHARSET
      )
    ).toOption.getOrElse(return None)

    val fields = decodedPayload.split(FIELD_SEPARATOR)
    if (fields.length != 3) return None

    val serviceId = fields(0)
    val targetService = fields(1)
    val timestamp = fields(2).toLongOption.getOrElse(return None)

    // Check token freshness (5 minute window)
    val now = System.currentTimeMillis() / 1000
    if (Math.abs(now - timestamp) > 300) return None

    // Verify target service matches
    if (!verifyServiceTarget(targetService, expectedTarget)) return None

    // Look up credential and verify signature
    val credential = trustedServices.get(serviceId).getOrElse(return None)
    val expectedPayload = s"${serviceId}${FIELD_SEPARATOR}${targetService}${FIELD_SEPARATOR}${timestamp}"
    val expectedSignature = computeHmac(credential.secret, expectedPayload)
    // Safely decode the provided signature; malformed Base64 results in None
    val providedSignature = Try(Base64.getUrlDecoder.decode(parts(1))).toOption.getOrElse(return None)

    if (MessageDigest.isEqual(expectedSignature, providedSignature)) {
      Some(credential)
    } else {
      None
    }
  }

  private def verifyServiceTarget(provided: String, expected: String): Boolean = {
    // Normalize both service identifiers before comparison
    val normalizedProvided = TokenEncoding.normalizeServiceId(provided)
    val normalizedExpected = TokenEncoding.normalizeServiceId(expected)
    MessageDigest.isEqual(normalizedProvided, normalizedExpected)
  }

  private def computeHmac(secret: Array[Byte], data: String): Array[Byte] = {
    val mac = Mac.getInstance(HMAC_ALGORITHM)
    mac.init(new SecretKeySpec(secret, HMAC_ALGORITHM))
    mac.doFinal(data.getBytes(TokenEncoding.SERVICE_CHARSET))
  }
}

class PermissionGateway(authenticator: CrossServiceAuthenticator) {

  def authorizeRequest(
    token: String, 
    targetService: String, 
    requiredPermission: String
  ): Either[String, ServiceCredential] = {

    authenticator.validateToken(token, targetService) match {
      case Some(credential) =>
        if (credential.permissions.contains(requiredPermission)) {
          Right(credential)
        } else {
          Left(s"Service ${credential.serviceId} lacks permission: $requiredPermission")
        }
      case None =>
        Left("Invalid or expired authentication token")
    }
  }

  def authorizeWithEscalation(
    token: String,
    targetService: String,
    requiredPermission: String,
    escalationToken: Option[String] = None
  ): Either[String, ServiceCredential] = {

    val baseAuth = authorizeRequest(token, targetService, requiredPermission)

    baseAuth match {
      case Right(cred) => Right(cred)
      case Left(_) if escalationToken.isDefined =>
        // Escalation path: verify the escalation token grants admin
        val escToken = escalationToken.get
        authenticator.validateToken(escToken, targetService) match {
          case Some(escCred) if escCred.permissions.contains("admin") =>
            // Admin escalation still requires the permission on the admin credential
            if (escCred.permissions.contains(requiredPermission)) {
              Right(escCred)
            } else {
              Left("Admin escalation credential lacks required permission")
            }
          case _ => Left("Escalation token invalid or lacks admin permission")
        }
      case left => left
    }
  }
}

object ServiceRegistry {
  def buildAuthenticator(configs: List[(String, String, Set[String])]): CrossServiceAuthenticator = {
    val credentials = configs.map { case (id, secretStr, perms) =>
      val secret = MessageDigest.getInstance("SHA-256").digest(secretStr.getBytes(StandardCharsets.UTF_8))
      id -> ServiceCredential(id, secret, perms)
    }.toMap
    new CrossServiceAuthenticator(credentials)
  }
}
